-- ── helpers ──────────────────────────────────────────────────────────

local function checkBuf(b)
    assert(type(b) == "table" and b.__type == "Buffer", "expected buffer")
end

local function checkRange(b, offset, size)
    assert(offset >= 0 and offset + size <= #b.__data,
        "buffer access out of range")
end

-- IEEE-754 float utils (pure Lua, no ffi)
local function packf32(v)
    if v ~= v then return 0x7FC00000 end  -- NaN
    if v == 1 / 0 then return 0x7F800000 end -- +Inf
    if v == -1 / 0 then return 0xFF800000 end -- -Inf
    local sign = 0
    if v < 0 then
        sign = 1; v = -v
    end
    if v == 0 then return sign * 0x80000000 end
    local exp = math.floor(math.log(v) / math.log(2))
    local mant = v / 2 ^ exp - 1
    exp = exp + 127
    if exp <= 0 then -- denormal
        mant = (v / 2 ^ -126)
        exp = 0
    elseif exp >= 255 then
        return (sign * 0x80000000) + 0x7F800000
    end
    mant = math.floor(mant * 0x800000 + 0.5) % 0x800000
    return sign * 0x80000000 + exp * 0x800000 + mant
end

local function unpackf32(bits)
    local sign = bits >= 0x80000000 and -1 or 1
    local exp  = (bits % 0x80000000) / 0x800000
    exp        = math.floor(exp)
    local mant = bits % 0x800000
    if exp == 255 then
        return mant ~= 0 and 0 / 0 or sign * (1 / 0)
    elseif exp == 0 then -- denormal
        return sign * mant / 0x800000 * 2 ^ -126
    end
    return sign * (1 + mant / 0x800000) * 2 ^ (exp - 127)
end

-- ── construction ─────────────────────────────────────────────────────

local function ToLua(data)
    return "Buffer.Decode([[".. buffer.Encode(data) .."]])"
end

function buffer.create(size)
    assert(type(size) == "number" and size >= 0 and size == math.floor(size),
        "size must be a non-negative integer")
