    for i = 1, size do data[i] = 0 end
    return setmetatable({ __type = "Buffer", __data = data },
        {
            __tostring = function() return "buffer(" .. tostring(size) .. ")" end,
            __index = {ToLua = ToLua},
        })
end

function buffer.Encode(buffer)
    return Buffer.readstring(buffer, 0, Buffer.len(buffer))
end

function buffer.Decode(data)
    local new = Buffer.create(data:len())
    buffer.writestring(new, 0, data)
    return new
end

---Return the byte length of the buffer.
function buffer.len(b)
