---Copy bytes from `src` into `dst`. Handles overlapping regions.
function buffer.copy(dst, dstOffset, src, srcOffset, count)
    checkBuf(dst); checkBuf(src)
    srcOffset = srcOffset or 0
    count     = count or (#src.__data - srcOffset)
    checkRange(src, srcOffset, count)
    checkRange(dst, dstOffset, count)
    if dstOffset > srcOffset then -- copy right-to-left for overlap safety
        for i = count - 1, 0, -1 do
            dst.__data[dstOffset + i + 1] = src.__data[srcOffset + i + 1]
        end
    else
        for i = 0, count - 1 do
            dst.__data[dstOffset + i + 1] = src.__data[srcOffset + i + 1]
        end
    end
