function buffer.writeu32(b, offset, value)
    checkBuf(b); checkRange(b, offset, 4)
    value = value % 0x100000000
    b.__data[offset + 1] = value % 256
    b.__data[offset + 2] = math.floor(value / 0x100) % 256
    b.__data[offset + 3] = math.floor(value / 0x10000) % 256
    b.__data[offset + 4] = math.floor(value / 0x1000000) % 256
