function buffer.readi16(b, offset)
    local v = buffer.readu16(b, offset)
    return v >= 0x8000 and v - 0x10000 or v
end

function buffer.writei16(b, offset, value)
    buffer.writeu16(b, offset, value % 0x10000)
end

function buffer.readi32(b, offset)
    local v = buffer.readu32(b, offset)
    return v >= 0x80000000 and v - 0x100000000 or v
