-- ── float read/write ──────────────────────────────────────────────────

function buffer.readf32(b, offset)
    local bits = buffer.readu32(b, offset)
    return unpackf32(bits)
end

function buffer.writef32(b, offset, value)
    buffer.writeu32(b, offset, packf32(value))
end

-- f64 — uses two u32 halves (lo/hi), pure-Lua IEEE-754 decomposition
function buffer.readf64(b, offset)
    checkBuf(b); checkRange(b, offset, 8)
    local d    = b.__data
    local lo   = d[offset + 1] + d[offset + 2] * 0x100
        + d[offset + 3] * 0x10000 + d[offset + 4] * 0x1000000
    local hi   = d[offset + 5] + d[offset + 6] * 0x100
        + d[offset + 7] * 0x10000 + d[offset + 8] * 0x1000000
    local sign = hi >= 0x80000000 and -1 or 1
    local exp  = math.floor((hi % 0x80000000) / 0x100000)
    local mant = (hi % 0x100000) * 0x100000000 + lo
    if exp == 0x7FF then
        return mant ~= 0 and 0 / 0 or sign * (1 / 0)
    elseif exp == 0 then
        return sign * mant / 2 ^ 52 * 2 ^ -1022
    end
    return sign * (1 + mant / 2 ^ 52) * 2 ^ (exp - 1023)
end

function buffer.writef64(b, offset, value)
    checkBuf(b); checkRange(b, offset, 8)
    local sign, hi, lo = 0, 0, 0
    if value ~= value then -- NaN
        hi, lo = 0x7FF80000, 0
    elseif value == 1 / 0 then
        hi = 0x7FF00000
    elseif value == -1 / 0 then
        hi = 0xFFF00000
    else
        if value < 0 then
            sign = 0x80000000; value = -value
        end
        if value > 0 then
            local exp = math.floor(math.log(value) / math.log(2))
            if exp > 1023 then
                hi = sign + 0x7FF00000
            else
                local mant = value / 2 ^ exp - 1
                exp = exp + 1023
                if exp <= 0 then
                    mant = value / 2 ^ -1022; exp = 0
                end
                local mhi = math.floor(mant * 0x100000)
                lo        = math.floor((mant * 0x100000 - mhi) * 0x100000000 + 0.5)
                hi        = sign + exp * 0x100000 + mhi
