    local d = b.__data
    d[offset + 1] = lo % 256
    d[offset + 2] = math.floor(lo / 0x100) % 256
    d[offset + 3] = math.floor(lo / 0x10000) % 256
    d[offset + 4] = math.floor(lo / 0x1000000) % 256
    d[offset + 5] = hi % 256
    d[offset + 6] = math.floor(hi / 0x100) % 256
    d[offset + 7] = math.floor(hi / 0x10000) % 256
    d[offset + 8] = math.floor(hi / 0x1000000) % 256
