-- ── string read/write ─────────────────────────────────────────────────

---Read `count` bytes at `offset` as a Lua string.
function buffer.readstring(b, offset, count)
    checkBuf(b); checkRange(b, offset, count)
    local t = {}
    for i = offset + 1, offset + count do
        t[#t + 1] = string.char(b.__data[i])
    end
    return table.concat(t)
end

---Write string `s` into the buffer starting at `offset`.
