    count = count or #s
    checkRange(b, offset, count)
    for i = 1, count do
        b.__data[offset + i] = string.byte(s, i)
    end
end
local function checkBits(offset, count)
  assert(type(offset) == "number" and offset == math.floor(offset) and offset >= 0,
    "bit offset must be a non-negative integer")
  assert(type(count) == "number" and count == math.floor(count)
    and count >= 1 and count <= 32,
    "bit count must be an integer between 1 and 32")
  assert(offset + count <= 32,
    "bit field (offset + count) must not exceed 32")
end

-- Build a bitmask of `n` ones (n <= 32), pure-Lua safe
local function mask(n)
  if n == 32 then return 0xFFFFFFFF end
  return 2^n - 1
end

-- ── buffer.readbits / writebits ───────────────────────────────────────

---Read an unsigned integer from `count` bits starting at bit `bitOffset`
---within the u32 at byte `byteOffset`. Bits are numbered 0 (LSB) to 31.
---
--- buffer.readbits(b, byteOffset, bitOffset, count) -> number
function buffer.readbits(b, byteOffset, bitOffset, count)
  checkBuf(b)
  checkBits(bitOffset, count)
  local word = buffer.readu32(b, byteOffset)      -- read 4-byte window
  local shifted = math.floor(word / 2^bitOffset)  -- shift right
  return shifted % (mask(count) + 1)              -- mask to `count` bits
end

---Write an unsigned integer `value` into `count` bits starting at bit
---`bitOffset` within the u32 at byte `byteOffset`. Other bits untouched.
---
--- buffer.writebits(b, byteOffset, bitOffset, count, value)
function buffer.writebits(b, byteOffset, bitOffset, count, value)
  checkBuf(b)
  checkBits(bitOffset, count)
  local m    = mask(count)
  value = math.floor(value) % (m + 1)             -- clamp to field width
  local word = buffer.readu32(b, byteOffset)      -- read existing u32
