  local low  = word % 2^bitOffset                  -- bits below field
  local high = math.floor(word / 2^(bitOffset+count)) * 2^(bitOffset+count)
  word = high + (value * 2^bitOffset) + low
  buffer.writeu32(b, byteOffset, word)
